import json
import os
import re
import shlex
import subprocess
import sys
from collections import Counter


def _iter_transcript_events(transcript_path: str):
    if not transcript_path or not os.path.exists(transcript_path):
        return
    try:
        with open(transcript_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    yield json.loads(line)
                except json.JSONDecodeError:
                    continue
    except OSError:
        return


def _extract_added_code_from_diff(diff_text: str) -> str:
    """从 unified diff 中提取新增代码行，跳过 +++ 文件头。"""
    lines = []
    for line in (diff_text or '').splitlines():
        if line.startswith('+++'):
            continue
        if line.startswith('+'):
            lines.append(line[1:])
    return '\n'.join(lines)


def _count_text_lines(content: str) -> int:
    return len((content or '').splitlines())


def _extract_accept_code(change, file_path: str = '') -> str:
    """从 Codex patch 事件中提取新增代码片段，不上报完整 diff。"""
    if isinstance(change, dict):
        change_type = change.get('type', '')
        if change_type == 'delete':
            return ''
        if change_type == 'update':
            unified_diff = change.get('unified_diff', '')
            if isinstance(unified_diff, str) and unified_diff.strip():
                return _extract_added_code_from_diff(unified_diff)
        for key in ('content', 'new_content', 'after'):
            value = change.get(key)
            if isinstance(value, str) and value.strip():
                return value
    if isinstance(change, str) and change.strip():
        return change
    return ''


def _extract_new_added_code(before_diff: str, after_section: str) -> str:
    """返回本轮新增的代码行，扣除本轮前已存在的 dirty diff。"""
    if not after_section or after_section == before_diff:
        return ''
    before_added = Counter(
        line for line in (before_diff or '').splitlines()
        if line.startswith('+') and not line.startswith('+++')
    )
    lines = []
    for line in after_section.splitlines():
        if not line.startswith('+') or line.startswith('+++'):
            continue
        if before_added[line] > 0:
            before_added[line] -= 1
            continue
        lines.append(line[1:])
    return '\n'.join(lines)


def _capture_git_diff(cwd: str) -> str:
    if not cwd or not os.path.isdir(cwd):
        return ''
    try:
        result = subprocess.run(
            ['git', 'diff', '--no-ext-diff', '--unified=0', '--', '.'],
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=10,
        )
        if result.returncode == 0:
            return result.stdout
    except Exception:
        pass
    return ''


def _iter_diff_file_sections(diff_text: str):
    current_file = ''
    current_lines = []
    for line in diff_text.splitlines():
        if line.startswith('diff --git '):
            if current_file and current_lines:
                yield current_file, '\n'.join(current_lines)
            current_file = ''
            current_lines = [line]
            parts = line.split(' ')
            if len(parts) >= 4:
                path = parts[3]
                current_file = path[2:] if path.startswith('b/') else path
            continue
        if current_lines:
            if line.startswith('+++ b/'):
                current_file = line[6:]
            current_lines.append(line)
    if current_file and current_lines:
        yield current_file, '\n'.join(current_lines)


def _collect_untracked_file_code(cwd: str, before_untracked: list[str]) -> list[tuple[str, str]]:
    if not cwd or not os.path.isdir(cwd):
        return []
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--exclude-standard'],
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=5,
        )
        if result.returncode != 0:
            return []
        before = set(before_untracked or [])
        added_files = [path for path in result.stdout.splitlines() if path and path not in before]
    except Exception:
        return []

    collected = []
    for rel_path in added_files:
        abs_path = os.path.join(cwd, rel_path)
        try:
            if os.path.getsize(abs_path) > 512 * 1024:
                continue
            with open(abs_path, 'r', encoding='utf-8') as f:
                content = f.read()
            if content.strip():
                collected.append((abs_path, content))
        except Exception:
            continue
    return collected


def _extract_shell_diff_reports(info: dict) -> list[tuple[str, str]]:
    snapshot = info.get('turn_git_snapshot') or {}
    cwd = snapshot.get('cwd') or ''
    before_diff = snapshot.get('diff') or ''
    after_diff = _capture_git_diff(cwd)
    reports = []

    if after_diff and after_diff != before_diff:
        before_sections = dict(_iter_diff_file_sections(before_diff))
        for rel_path, section in _iter_diff_file_sections(after_diff):
            if before_sections.get(rel_path) == section:
                continue
            accept_code = _extract_new_added_code(before_sections.get(rel_path, ''), section)
            if accept_code.strip():
                reports.append((os.path.join(cwd, rel_path), accept_code))

    reports.extend(_collect_untracked_file_code(cwd, snapshot.get('untracked_files') or []))
    return reports


def _event_strings(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for child in value.values():
            yield from _event_strings(child)
    elif isinstance(value, list):
        for child in value:
            yield from _event_strings(child)


def _normalize_path(path: str) -> str:
    """Normalize path separators to '/' for cross-platform deduplication and server-side basename."""
    return path.replace('\\', '/')


def _looks_like_text_file(path: str) -> bool:
    _, ext = os.path.splitext(path.lower())
    return ext in {
        '.py', '.js', '.ts', '.tsx', '.jsx', '.java', '.go', '.rs', '.c', '.cc', '.cpp', '.h', '.hpp',
        '.cs', '.php', '.rb', '.swift', '.kt', '.scala', '.sh', '.bash', '.zsh', '.fish', '.sql', '.html',
        '.css', '.scss', '.json', '.yaml', '.yml', '.toml', '.xml', '.md', '.txt', '.ini', '.cfg', '.conf',
    }


def _extract_cat_heredoc_reports_from_command(command: str) -> list[tuple[str, str]]:
    reports = []
    pattern = re.compile(
        r"cat\s+>\s+(?P<path>(?:'[^']+'|\"[^\"]+\"|\S+))\s+<<\s*(?P<quote>['\"]?)(?P<tag>[A-Za-z_][A-Za-z0-9_]*)\2\s*\n(?P<body>.*?)(?:\n(?P=tag)(?:\n|$))",
        re.DOTALL,
    )
    for match in pattern.finditer(command):
        raw_path = match.group('path')
        try:
            parts = shlex.split(raw_path)
            file_path = parts[0] if parts else raw_path.strip('"\'')
        except ValueError:
            file_path = raw_path.strip('"\'')
        body = match.group('body')
        if file_path and body.strip() and _looks_like_text_file(file_path):
            reports.append((file_path, body))
    return reports


def _extract_shell_heredoc_reports(transcript_path: str) -> list[tuple[str, str]]:
    reports = []
    seen = set()
    for event in _iter_transcript_events(transcript_path) or []:
        for text in _event_strings(event):
            if 'cat' not in text or '<<' not in text or '>' not in text:
                continue
            for file_path, content in _extract_cat_heredoc_reports_from_command(text):
                key = (file_path, content)
                if key in seen:
                    continue
                seen.add(key)
                reports.append((file_path, content))
    return reports


def _extract_patch_events(transcript_path: str):
    for event in _iter_transcript_events(transcript_path) or []:
        if event.get('type') != 'event_msg':
            continue
        payload = event.get('payload') or {}
        if payload.get('type') != 'patch_apply_end' or not payload.get('success'):
            continue
        changes = payload.get('changes') or {}
        if not changes:
            continue
        yield {
            'call_id': payload.get('call_id', ''),
            'turn_id': payload.get('turn_id', ''),
            'changes': changes,
        }


def handle_stop():
    # Stop hook 绝对不能以非 0 退出，否则 Codex 会中断会话并要求 resume
    try:
        _do_handle_stop()
    except Exception:
        pass


def _do_handle_stop():
    from ahclaude_plugin.hook.logger import hook_log, hook_log_raw

    try:
        raw = sys.stdin.buffer.read()
        input_data = json.loads(raw.decode('utf-8'))
    except Exception as e:
        hook_log('stop_skip', f'codex stop输入不是JSON: {e}')
        return

    session_id = input_data.get('session_id', '')
    transcript_path = input_data.get('transcript_path', '')
    model_name = input_data.get('model')
    input_cwd = input_data.get('cwd', '')
    if not session_id:
        hook_log('stop_skip', 'codex stop缺少session_id')
        return
    if not transcript_path:
        hook_log('stop_skip', 'codex stop缺少transcript_path', session_id=session_id)
        return
    if not os.path.exists(transcript_path):
        hook_log('stop_skip', f'codex stop transcript不存在: {transcript_path}', session_id=session_id)
        return

    hook_log_raw('stop', input_data)

    try:
        from ahclaude_plugin.session_cache import get_session_info, mark_patch_reported
        from ahclaude_plugin.hook.report_helper import report_adoption_for_codex_patch

        info = get_session_info(session_id)
        session_seq = info['session_seq']
        current_turn = info['current_turn']
        repo_cwd = (info.get('turn_git_snapshot') or {}).get('cwd') or input_cwd
        reported_files = 0
        patch_events = 0
        skipped_files = 0

        patch_reported_files = set()

        for patch_event in _extract_patch_events(transcript_path):
            patch_events += 1
            call_id = patch_event.get('call_id') or patch_event.get('turn_id') or f'patch_{patch_events}'

            for file_index, (file_path, change) in enumerate(patch_event.get('changes', {}).items(), start=1):
                norm_path = _normalize_path(file_path)
                report_key = f'{call_id}:{norm_path}'
                if not mark_patch_reported(session_id, report_key):
                    patch_reported_files.add(norm_path)
                    continue
                accept_code = _extract_accept_code(change, norm_path)
                if not accept_code or not accept_code.strip():
                    skipped_files += 1
                    continue
                report_adoption_for_codex_patch(
                    norm_path,
                    accept_code,
                    session_id,
                    model_name=model_name,
                    session_seq=session_seq,
                    turn=current_turn,
                    call_id=f'{call_id}_{file_index}',
                    repository_path=repo_cwd,
                    accept_line_count=len(accept_code.splitlines()),
                )
                patch_reported_files.add(norm_path)
                reported_files += 1

        for file_index, (file_path, accept_code) in enumerate(_extract_shell_diff_reports(info), start=1):
            norm_path = _normalize_path(file_path)
            if norm_path in patch_reported_files:
                continue
            report_key = f'shell:{current_turn}:{norm_path}'
            if not mark_patch_reported(session_id, report_key):
                continue
            report_adoption_for_codex_patch(
                norm_path,
                accept_code,
                session_id,
                model_name=model_name,
                session_seq=session_seq,
                turn=current_turn,
                call_id=f'shell_{current_turn}_{file_index}',
                repository_path=repo_cwd,
                accept_line_count=len(accept_code.splitlines()),
            )
            reported_files += 1

        for file_index, (file_path, accept_code) in enumerate(_extract_shell_heredoc_reports(transcript_path), start=1):
            norm_path = _normalize_path(file_path)
            if norm_path in patch_reported_files:
                continue
            report_key = f'heredoc:{current_turn}:{norm_path}'
            if not mark_patch_reported(session_id, report_key):
                continue
            report_adoption_for_codex_patch(
                norm_path,
                accept_code,
                session_id,
                model_name=model_name,
                session_seq=session_seq,
                turn=current_turn,
                call_id=f'heredoc_{current_turn}_{file_index}',
                repository_path=repo_cwd,
                accept_line_count=len(accept_code.splitlines()),
            )
            reported_files += 1

        if reported_files:
            hook_log('stop', f'codex patch解析完成: files={reported_files}', session_id=session_id)
        else:
            hook_log('stop_skip', f'codex stop未解析到可上报patch: events={patch_events}, skipped_files={skipped_files}', session_id=session_id)
    except Exception as e:
        import traceback
        hook_log('error', f'cmd_stop 处理失败: {e}', session_id=session_id, extra={
            'traceback': traceback.format_exc().strip(),
        })


if __name__ == '__main__':
    handle_stop()
